0) - ((b.order ?? b.displayOrder) || 0));\n    const certificates = [...(db.certificates || initialCertificates)].sort((a: any, b: any) => ((a.order ?? a.displayOrder) || 0) - ((b.order ?? b.displayOrder) || 0));\n    const achievements = [...(db.achievements || initialAchievements)].sort((a: any, b: any) => ((a.order ?? a.displayOrder) || 0) - ((b.order ?? b.displayOrder) || 0));\n    const experiences = [...(db.experiences || initialExperiences)].sort((a: any, b: any) => ((a.order ?? a.displayOrder) || 0) - ((b.order ?? b.displayOrder) || 0));\n    const education = [...(db.education || initialEducation)].sort((a: any, b: any) => ((a.order ?? a.displayOrder) || 0) - ((b.order ?? b.displayOrder) || 0));\n    const analytics = db.analytics || initialAnalytics;\n    const settings = db.settings || initialSettings;\n    const footer = db.footer || initialFooter;\n    const socialLinks = [...(db.socialLinks || initialSocialLinks)].sort((a: any, b: any) => ((a.order ?? a.displayOrder) || 0) - ((b.order ?? b.displayOrder) || 0));\n    const footerSocialLinks = [...(db.footerSocialLinks || [])].sort((a: any, b: any) => ((a.order ?? a.displayOrder) || 0) - ((b.order ?? b.displayOrder) || 0));\n    const codingProfiles = [...(db.codingProfiles || [])].sort((a: any, b: any) => ((a.order ?? a.displayOrder) || 0) - ((b.order ?? b.displayOrder) || 0));\n    const technologies = [...(db.technologies || initialTechStack)].sort((a: any, b: any) => ((a.order ?? a.displayOrder) || 0) - ((b.order ?? b.displayOrder) || 0));\n    const portfolioMetrics = [...(db.portfolioMetrics || initialPortfolioMetrics)].sort((a: any, b: any) => ((a.order ?? a.displayOrder) || 0) - ((b.order ?? b.displayOrder) || 0));\n    const testimonials = [...(db.testimonials || initialTestimonials)].sort((a: any, b: any) => ((a.order ?? a.displayOrder) || 0) - ((b.order ?? b.displayOrder) || 0));\n    const articles = [...(db.articles || initialArticles)].sort((a: any, b: any) => {\n      const orderA = (a.order ?? a.displayOrder);\n      const orderB = (b.order ?? b.displayOrder);\n      if (orderA !== undefined && orderB !== undefined && orderA !== orderB) {\n        return orderA - orderB;\n      }\n      return new Date(b.publishedAt || b.createdAt || 0).getTime() - new Date(a.publishedAt || a.createdAt || 0).getTime();\n    });\n    const profile = db.profile || initialProfile;\n    const themeSettings = db.themeSettings || initialThemeSettings;\n\n    const consolidatedData = {\n      profile,\n      settings,\n      theme: themeSettings,\n      footer,\n      projects,\n      skills,\n      tools,\n      certificates,\n      achievements,\n      experiences,\n      education,\n      analytics,\n      socialLinks,\n      footerSocialLinks,\n      codingProfiles,\n      technologies,\n      portfolioMetrics,\n      testimonials,\n      articles,\n      activeResume,\n      resumes\n    };\n\n    cachedPortfolioData = consolidatedData;\n    res.json(consolidatedData);\n  };\n\n  app.get([\"/api/portfolio-combined\", \"/portfolio-combined\", \"/api/portfolio\", \"/portfolio\", \"/api/portfolio-data\"], getPortfolioCombinedHandler);\n\n  // Profile API Endpoints\n  app.get(\"/api/profile\", (req, res) => {\n    const db = loadDatabase();\n    const oldResumeUrl = db.profile?.resumeUrl;\n    syncProfileActiveResume(db);\n    if (oldResumeUrl !== db.profile?.resumeUrl) {\n      saveDatabase(db);\n    }\n    if (!db.users || !Array.isArray(db.users) || db.users.length === 0) {\n      db.users = [{\n        id: 1,\n        name: \"Chandru Mohan\",\n        email: \"chandrumohan550@gmail.com\",\n        username: \"chandru\",\n        phoneNumber: \"+919655384140\",\n        role: \"ROLE_ADMIN\",\n        isActive: true\n      }];\n    }\n    const user = db.users[0];\n    const profile = db.profile || initialProfile;\n    res.json({\n      ...profile,\n      username: user?.username || \"chandru\",\n      phoneNumber: user?.phoneNumber || \"+919655384140\",\n      backupEmail: user?.backupEmail || \"\",\n      recoveryPhoneNumber: user?.recoveryPhoneNumber || \"\"\n    });\n  });\n\n  app.put(\"/api/profile\", authenticateJWT, (req: any, res: any) => {\n    const db = loadDatabase();\n    if (!db.users || !Array.isArray(db.users) || db.users.length === 0) {\n      db.users = [{\n        id: 1,\n        name: \"Chandru Mohan\",\n        email: \"chandrumohan550@gmail.com\",\n        username: \"chandru\",\n        phoneNumber: \"+919655384140\",\n        role: \"ROLE_ADMIN\",\n        isActive: true\n      }];\n    }\n    const user = db.users[0];\n    const oldValue = { ...(db.profile || initialProfile) };\n    const updated = req.body || {};\n    \n    if (!db.profile) db.profile = { ...initialProfile };\n\n    // Merge incoming properties directly to db.profile\n    Object.keys(updated).forEach((key) => {\n      if (updated[key] !== undefined) {\n        db.profile[key] = updated[key];\n      }\n    });\n\n    // Only synchronize aliases when only one side is explicitly provided\n    if (updated.fullName !== undefined && updated.heroName === undefined) {\n      db.profile.heroName = updated.fullName;\n    } else if (updated.heroName !== undefined && updated.fullName === undefined) {\n      db.profile.fullName = updated.heroName;\n    }\n\n    if (updated.title !== undefined && updated.heroTitle === undefined) {\n      db.profile.heroTitle = updated.title;\n    } else if (updated.heroTitle !== undefined && updated.title === undefined) {\n      db.profile.title = updated.heroTitle;\n    }\n\n    if (updated.shortTagline !== undefined && updated.heroSubtitle === undefined) {\n      db.profile.heroSubtitle = updated.shortTagline;\n    } else if (updated.heroSubtitle !== undefined && updated.shortTagline === undefined) {\n      db.profile.shortTagline = updated.heroSubtitle;\n    }\n\n    if (updated.shortIntroduction !== undefined && updated.heroDescription === undefined) {\n      db.profile.heroDescription = updated.shortIntroduction;\n    } else if (updated.heroDescription !== undefined && updated.shortIntroduction === undefined) {\n      db.profile.shortIntroduction = updated.heroDescription;\n    }\n\n    if (updated.heroVisibility !== undefined) {\n      db.profile.heroVisibility = updated.heroVisibility !== false;\n    }\n\n    db.profile.updatedAt = new Date().toISOString();\n    \n    // Update Founder user details safely\n    if (user) {\n      user.name = db.profile.fullName || user.name || \"Chandru Mohan\";\n      user.email = db.profile.email || user.email || \"chandrumohan550@gmail.com\";\n      user.phoneNumber = db.profile.phone || db.profile.phoneNumber || user.phoneNumber || \"+919655384140\";\n      user.username = updated.username || user.username || \"chandru\";\n      user.backupEmail = updated.backupEmail !== undefined ? updated.backupEmail : user.backupEmail;\n      user.recoveryPhoneNumber = updated.recoveryPhoneNumber !== undefined ? updated.recoveryPhoneNumber : user.recoveryPhoneNumber;\n      \n      if (updated.password) {\n        const salt = bcrypt.genSaltSync(10);\n        user.passwordHash = bcrypt.hashSync(updated.password, salt);\n      }\n      \n      user.updatedAt = new Date().toISOString();\n    }\n    \n    recordActivity(req, db, {\n      action: \"Profile Updated\",\n      module: \"Profile\",\n      description: \"Founder updated profile and hero presentation details.\",\n      oldValue,\n      newValue: {\n        ...db.profile,\n        username: user?.username || \"chandru\",\n        backupEmail: user?.backupEmail || \"\",\n        recoveryPhoneNumber: user?.recoveryPhoneNumber || \"\"\n      }\n    });\n    \n    syncProfileActiveResume(db);\n    saveDatabase(db);\n    res.json({\n      ...db.profile,\n      username: user?.username || \"chandru\",\n      phoneNumber: user?.phoneNumber || \"+919655384140\",\n      backupEmail: user?.backupEmail || \"\",\n      recoveryPhoneNumber: user?.recoveryPhoneNumber || \"\"\n    });\n  });\n\n  // Profile Image Patch and Delete Handlers (Supporting Hero and Profile pages)\n  const handleProfileImagePatch = (fieldName: string) => (req: any, res: any) => {\n    const db = loadDatabase();\n    const { image } = req.body;\n    if (!db.profile) db.profile = { ...initialProfile };\n    \n    let processedUrl = image || \"\";\n    if (processedUrl && processedUrl.startsWith(\"data:\")) {\n      const processed = processMockCloudinaryImage(processedUrl, fieldName);\n      processedUrl = processed.url;\n    }\n    \n    db.profile[fieldName] = processedUrl;\n    if (fieldName === 'websiteLogo') {\n      db.profile.logoUrl = processedUrl;\n    }\n    db.profile.updatedAt = new Date().toISOString();\n    saveDatabase(db);\n    res.json({ status: \"success\", profile: db.profile });\n  };\n\n  const handleProfileImageDelete = (fieldName: string) => (req: any, res: any) => {\n    const db = loadDatabase();\n    if (!db.profile) db.profile = { ...initialProfile };\n    db.profile[fieldName] = \"\";\n    if (fieldName === 'websiteLogo') {\n      db.profile.logoUrl = \"\";\n    }\n    db.profile.updatedAt = new Date().toISOString();\n    saveDatabase(db);\n    res.json({ status: \"success\", profile: db.profile });\n  };\n\n  app.patch(\"/api/profile/hero-avatar\", authenticateJWT, handleProfileImagePatch(\"heroAvatar\"));\n  app.delete(\"/api/profile/hero-avatar\", authenticateJWT, handleProfileImageDelete(\"heroAvatar\"));\n\n  app.patch(\"/api/profile/hero-background\", authenticateJWT, handleProfileImagePatch(\"heroBackground\"));\n  app.delete(\"/api/profile/hero-background\", authenticateJWT, handleProfileImageDelete(\"heroBackground\"));\n\n  app.patch(\"/api/profile/profile-image\", authenticateJWT, handleProfileImagePatch(\"profileImage\"));\n  app.delete(\"/api/profile/profile-image\", authenticateJWT, handleProfileImageDelete(\"profileImage\"));\n\n  app.patch(\"/api/profile/cover-image\", authenticateJWT, handleProfileImagePatch(\"coverImage\"));\n  app.delete(\"/api/pro